function EFFECTIVE_SUPPORT(p):
    return 1 / sum_i p[i]^2

function CONCENTRATION_CAP(p, k):
    return sqrt(k / EFFECTIVE_SUPPORT(p))                   # >= TOP_K_MASS(p,k)

function MIN_BUDGET_FOR_MASS(p, beta):
    return beta^2 * EFFECTIVE_SUPPORT(p)                    # <= any such budget

function SPLIT(p[1..L]):
    out <- empty
    for each weight x in p:
        append x/2 and x/2 to out
    return out                                              # length 2L

function EXCHANGE_TEST(p, k):
    a <- max over all k-subsets S of sum_{i in S} p[i]
    b <- max over all 2k-subsets U of SPLIT(p) of sum_{q in U} SPLIT(p)[q]
    return |a - b|                                          # exactly 0

