function KNEE(sweep, bar):
    for (k, retained) in sweep sorted by increasing k:
        if retained >= bar:
            return k
    return NONE                     # no grid point clears the bar

function ROBUSTNESS_RADIUS(sweep, bar):
    k* <- KNEE(sweep, bar)
    if k* is NONE: error
    margin   <- retained(k*) - bar
    deficits <- { bar - retained(j) : (j, .) in sweep, j < k* }
    return min(margin, min deficits)          # exact, both directions proved

function ADMISSIBLE_READINGS(sweep, bar, eta):
    readings <- empty set
    for sign in {+1, -1}:
        shifted <- { (k, retained + sign*eta) }
        insert KNEE(shifted, bar) into readings
    return sorted readings

function CERTIFICATION_DEPTH(margins[0..n-1], eta):
    for i from 0 to n-1:
        if not (eta <= margins[i]):
            return i                       # first rung the noise destroys
    return n

function COLLAPSE_PROFILE(margins[0..n-1]):
    running <- +infinity
    profile <- empty list
    for i from 0 to n-1:
        running <- min(running, margins[i])
        append (running, i+1) to profile   # depth i+1 needs eta <= running
    return profile sorted by decreasing threshold

function WEAKEST_LINK(margins):
    i <- argmin_i margins[i]
    return (i, margins[i])
